  array( 'module' => 'shipping_calculator', 'group' => 'calculator-fields', 'label' => 'City, postcode and state inputs', 'consequence' => 'Choose which address fields the shipping calculator asks shoppers to enter. Hiding a city, postcode or state field can change the address information available for calculating shipping. Check a test cart with representative destinations, especially where your rates depend on those fields.', 'guide' => 'https://booster.io/docs/woocommerce-shipping-calculator-customizer/#booster-v10-s16-calculator-fields', 'native_by_edition' => array( 'free' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_calculator&active_tab=shipping_calculator_general_options_tab' ), 'reason' => 'Native source surface present' ), 'plus' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_calculator&active_tab=shipping_calculator_general_options_tab' ), 'reason' => 'Native source surface present' ), 'elite' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_calculator&active_tab=shipping_calculator_general_options_tab' ), 'reason' => 'Native source surface present' ) ) ),
