  array( 'module' => 'shipping_description', 'group' => 'description-identity', 'label' => 'Apply descriptions to a method or zone instance', 'consequence' => 'Choose a method-wide description to use the wording for matching shipping choices across zones and packages, or use instances to write wording for one option added to a zone. Switching does not move or delete the other saved descriptions. The plain-text task edits one supported existing Flat rate, Free shipping or Local pickup choice at a time.', 'guide' => 'https://booster.io/docs/woocommerce-shipping-descriptions/#booster-v10-s16-description-identity', 'native_by_edition' => array( 'free' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_description&active_tab=shipping_description_shipping_method_descriptions_tab' ), 'reason' => 'Native source surface present' ), 'plus' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_description&active_tab=shipping_description_shipping_method_descriptions_tab' ), 'reason' => 'Native source surface present' ), 'elite' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_description&active_tab=shipping_description_shipping_method_descriptions_tab' ), 'reason' => 'Native source surface present' ) ) ),
  array( 'module' => 'shipping_description', 'group' => 'description-placement', 'label' => 'Where descriptions appear', 'consequence' => 'When enabled, Free shows descriptions after the shipping label on both cart and checkout. Plus and Elite can choose before, after or Instead, and cart-only or checkout-only visibility in full settings. Instead replaces the full label, including its displayed price. Use full settings for Instead or a custom placement; the plain-text task leaves these choices unchanged.', 'guide' => 'https://booster.io/docs/woocommerce-shipping-descriptions/#booster-v10-s16-description-placement', 'native_by_edition' => array( 'free' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_description&active_tab=shipping_description_general_options_tab' ), 'reason' => 'Native source surface present' ), 'plus' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_description&active_tab=shipping_description_general_options_tab' ), 'reason' => 'Native source surface present' ), 'elite' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_description&active_tab=shipping_description_general_options_tab' ), 'reason' => 'Native source surface present' ) ) ),
  array( 'module' => 'shipping_description', 'group' => 'description-text', 'label' => 'Description text and formatting', 'consequence' => 'Use full settings for HTML, shortcodes or other custom formatting. The plain-text task keeps supported existing text exactly and accepts one line up to 500 UTF-8 bytes; some characters use more than one byte. Include your own space or punctuation where the text meets the shipping label. A description is not a delivery guarantee; check its appearance on your actual cart and checkout, including any Blocks layout.', 'guide' => 'https://booster.io/docs/woocommerce-shipping-descriptions/#booster-v10-s16-description-text', 'native_by_edition' => array( 'free' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_description&active_tab=shipping_description_shipping_method_descriptions_tab' ), 'reason' => 'Native source surface present' ), 'plus' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_description&active_tab=shipping_description_shipping_method_descriptions_tab' ), 'reason' => 'Native source surface present' ), 'elite' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_description&active_tab=shipping_description_shipping_method_descriptions_tab' ), 'reason' => 'Native source surface present' ) ) ),
