  array( 'module' => 'shipping_options', 'group' => 'product-free-grant', 'label' => 'Free shipping for qualifying products', 'consequence' => 'Use these settings to grant free shipping based on the products in the cart. Check whether all products must qualify or whether the paid at-least-one option is selected. This is separate from hiding other rates when Free shipping is offered, and a remaining-amount message does not decide whether products qualify.', 'guide' => 'https://booster.io/docs/woocommerce-shipping-options/#booster-v10-s16-product-free-grant', 'native_by_edition' => array( 'free' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_options&active_tab=shipping__order_amount_tab' ), 'reason' => 'Native source surface present' ), 'plus' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_options&active_tab=shipping__order_amount_tab' ), 'reason' => 'Native source surface present' ), 'elite' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_options&active_tab=shipping__order_amount_tab' ), 'reason' => 'Native source surface present' ) ) ),
  array( 'module' => 'shipping_options', 'group' => 'most-expensive', 'label' => 'Keep the most expensive rate and choose exceptions', 'consequence' => 'These settings can remove other shipping choices and keep the most expensive one; they do not simply reorder the list. Choosing methods to ignore requires the supported paid edition. Check each relevant package in a test cart. Local pickup can have a charge, and a zero-cost Flat rate is not the WooCommerce Free shipping method.', 'guide' => 'https://booster.io/docs/woocommerce-shipping-options/#booster-v10-s16-most-expensive', 'native_by_edition' => array( 'free' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_options&active_tab=shipping__show_only_tab' ), 'reason' => 'Native source surface present' ), 'plus' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_options&active_tab=shipping__show_only_tab' ), 'reason' => 'Native source surface present' ), 'elite' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_options&active_tab=shipping__show_only_tab' ), 'reason' => 'Native source surface present' ) ) ),
  array( 'module' => 'shipping_options', 'group' => 'hide-other-rates', 'label' => 'Hide other rates: mode and rule order', 'consequence' => 'Choose which other rates to hide when Free shipping is offered, using the options available in your edition. Filter Priority controls when this rule runs: higher numbers run later. Check the result alongside your other shipping rules. The guided hide-other-rates task is available separately; description Undo does not undo these settings.', 'guide' => 'https://booster.io/docs/woocommerce-shipping-options/#booster-v10-s16-hide-other-rates', 'native_by_edition' => array( 'free' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_options&active_tab=shipping_general_options_tab' ), 'reason' => 'Native source surface present' ), 'plus' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_options&active_tab=shipping_general_options_tab' ), 'reason' => 'Native source surface present' ), 'elite' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_options&active_tab=shipping_general_options_tab' ), 'reason' => 'Native source surface present' ) ) ),
  array( 'module' => 'shipping_options', 'group' => 'shipping_options-activation', 'label' => 'Module activation and access', 'consequence' => 'Switching this module on can activate earlier settings for several shipping choices. Review those settings first. Access depends on the permissions set by your administrator. Opening help or saving description text does not switch a module or shipping method on.', 'guide' => 'https://booster.io/docs/woocommerce-shipping-options/#booster-v10-s16-shipping_options-activation', 'native_by_edition' => array( 'free' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_options' ), 'reason' => 'Native source surface present' ), 'plus' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_options' ), 'reason' => 'Native source surface present' ), 'elite' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_options' ), 'reason' => 'Native source surface present' ) ) ),
