  array( 'module' => 'shipping_time', 'group' => 'time-identity', 'label' => 'Delivery estimates by method, zone instance or class', 'consequence' => 'Choose estimates for a shipping method across zones or for one instance added to a zone. Plus and Elite can also use shipping-class-specific estimates. Check the selected method and class before editing. These values describe an estimate; they do not set carrier transit times or decide whether a shipping choice is available.', 'guide' => 'https://booster.io/docs/woocommerce-shipping-time/#booster-v10-s16-time-identity', 'native_by_edition' => array( 'free' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_time&active_tab=shipping_time_general_options_tab' ), 'reason' => 'Native source surface present' ), 'plus' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_time&active_tab=shipping_time_general_options_tab' ), 'reason' => 'Native source surface present' ), 'elite' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_time&active_tab=shipping_time_general_options_tab' ), 'reason' => 'Native source surface present' ) ) ),
  array( 'module' => 'shipping_time', 'group' => 'time-estimate', 'label' => 'Delivery estimate text and shortcodes', 'consequence' => 'Set the estimate values here, then display them where needed with the shipping-time shortcodes. Use wcj_shipping_time_table for a table, optionally selecting a shipping class with shipping_class_term_id; use wcj_product_shipping_time_table in the relevant product context. Edit the content where you placed the shortcode and check its output. These are estimates, not guaranteed delivery dates, and they do not automatically replace shipping labels.', 'guide' => 'https://booster.io/docs/woocommerce-shipping-time/#booster-v10-s16-time-estimate', 'native_by_edition' => array( 'free' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_time&active_tab=shipping_time_shipping_time_tab' ), 'reason' => 'Native source surface present' ), 'plus' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_time&active_tab=shipping_time_shipping_time_tab' ), 'reason' => 'Native source surface present' ), 'elite' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_time&active_tab=shipping_time_shipping_time_tab' ), 'reason' => 'Native source surface present' ) ) ),
  array( 'module' => 'shipping_time', 'group' => 'shipping_time-activation', 'label' => 'Module activation and access', 'consequence' => 'Switching this module on can activate earlier settings for several shipping choices. Review those settings first. Access depends on the permissions set by your administrator. Opening help or saving description text does not switch a module or shipping method on.', 'guide' => 'https://booster.io/docs/woocommerce-shipping-time/#booster-v10-s16-shipping_time-activation', 'native_by_edition' => array( 'free' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_time' ), 'reason' => 'Native source surface present' ), 'plus' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_time' ), 'reason' => 'Native source surface present' ), 'elite' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_time' ), 'reason' => 'Native source surface present' ) ) ),
