  array( 'module' => 'shipping_by_cities', 'group' => 'shipping_by_cities-identity', 'label' => 'Apply restrictions to a method or zone instance', 'consequence' => 'Choose a shipping method across zones or one instance added to a zone, then enable the relevant restriction section. Each choice has separate saved settings; switching does not move or delete the other set. Free supports Flat rate and Local pickup here. Free shipping and other supported methods require Plus or Elite. Check any customer-role selection separately.', 'guide' => 'https://booster.io/docs/woocommerce-shipping-methods-by-cities/#booster-v10-s16-shipping_by_cities-identity', 'native_by_edition' => array( 'free' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_by_cities&active_tab=shipping_by_condition_general_options_tab' ), 'reason' => 'Native source surface present' ), 'plus' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_by_cities&active_tab=shipping_by_condition_general_options_tab' ), 'reason' => 'Native source surface present' ), 'elite' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_by_cities&active_tab=shipping_by_condition_general_options_tab' ), 'reason' => 'Native source surface present' ) ) ),
  array( 'module' => 'shipping_by_cities', 'group' => 'shipping_by_cities-priority', 'label' => 'Order of shipping rule checks', 'consequence' => 'Filter Priority controls when this restriction runs alongside other shipping rules. Higher numbers run later, and a later rule can remove a choice that an earlier rule kept. Change the priority only when you need a different order, then check the resulting choices in a representative test cart.', 'guide' => 'https://booster.io/docs/woocommerce-shipping-methods-by-cities/#booster-v10-s16-shipping_by_cities-priority', 'native_by_edition' => array( 'free' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_by_cities&active_tab=shipping_by_condition_advanced_options_tab' ), 'reason' => 'Native source surface present' ), 'plus' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_by_cities&active_tab=shipping_by_condition_advanced_options_tab' ), 'reason' => 'Native source surface present' ), 'elite' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_by_cities&active_tab=shipping_by_condition_advanced_options_tab' ), 'reason' => 'Native source surface present' ) ) ),
  array( 'module' => 'shipping_by_cities', 'group' => 'shipping_by_cities-cities', 'label' => 'Cities to include or exclude', 'consequence' => 'Enter one city per line. Comparisons ignore letter case and spaces around each entry. The rule uses the accepted checkout city when supplied, otherwise the calculator city, then the saved shipping city or store base city. Check the destination used by your test cart; matching a city does not override other shipping restrictions.', 'guide' => 'https://booster.io/docs/woocommerce-shipping-methods-by-cities/#booster-v10-s16-shipping_by_cities-cities', 'native_by_edition' => array( 'free' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_by_cities&active_tab=shipping_by_condition_by_cities_tab' ), 'reason' => 'Native source surface present' ), 'plus' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_by_cities&active_tab=shipping_by_condition_by_cities_tab' ), 'reason' => 'Native source surface present' ), 'elite' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_by_cities&active_tab=shipping_by_condition_by_cities_tab' ), 'reason' => 'Native source surface present' ) ) ),
  array( 'module' => 'shipping_by_cities', 'group' => 'shipping_by_cities-postcodes', 'label' => 'Postcodes to include or exclude', 'consequence' => 'Enter the postcodes or supported postcode patterns for the methods you want to include or exclude. Comparisons ignore letter case and surrounding spaces. The rule uses the accepted checkout postcode when supplied, otherwise the saved shipping postcode or store base postcode. Check your patterns with representative destinations in a test cart.', 'guide' => 'https://booster.io/docs/woocommerce-shipping-methods-by-cities/#booster-v10-s16-shipping_by_cities-postcodes', 'native_by_edition' => array( 'free' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_by_cities&active_tab=shipping_by_condition_by_postcodes_tab' ), 'reason' => 'Native source surface present' ), 'plus' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_by_cities&active_tab=shipping_by_condition_by_postcodes_tab' ), 'reason' => 'Native source surface present' ), 'elite' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_by_cities&active_tab=shipping_by_condition_by_postcodes_tab' ), 'reason' => 'Native source surface present' ) ) ),
  array( 'module' => 'shipping_by_cities', 'group' => 'shipping_by_cities-activation', 'label' => 'Module activation and access', 'consequence' => 'Switching this module on can activate earlier settings for several shipping choices. Review those settings first. Access depends on the permissions set by your administrator. Opening help or saving description text does not switch a module or shipping method on.', 'guide' => 'https://booster.io/docs/woocommerce-shipping-methods-by-cities/#booster-v10-s16-shipping_by_cities-activation', 'native_by_edition' => array( 'free' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_by_cities' ), 'reason' => 'Native source surface present' ), 'plus' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_by_cities' ), 'reason' => 'Native source surface present' ), 'elite' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_by_cities' ), 'reason' => 'Native source surface present' ) ) ),
