  array( 'module' => 'shipping_by_products', 'group' => 'shipping_by_products-identity', 'label' => 'Apply restrictions to a method or zone instance', 'consequence' => 'Choose a shipping method across zones or one instance added to a zone, then enable the relevant restriction section. Each choice has separate saved settings; switching does not move or delete the other set. Free supports Flat rate and Local pickup here. Free shipping and other supported methods require Plus or Elite. Check any customer-role selection separately.', 'guide' => 'https://booster.io/docs/woocommerce-shipping-methods-by-products/#booster-v10-s16-shipping_by_products-identity', 'native_by_edition' => array( 'free' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_by_products&active_tab=shipping_by_condition_general_options_tab' ), 'reason' => 'Native source surface present' ), 'plus' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_by_products&active_tab=shipping_by_condition_general_options_tab' ), 'reason' => 'Native source surface present' ), 'elite' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_by_products&active_tab=shipping_by_condition_general_options_tab' ), 'reason' => 'Native source surface present' ) ) ),
  array( 'module' => 'shipping_by_products', 'group' => 'shipping_by_products-priority', 'label' => 'Order of shipping rule checks', 'consequence' => 'Filter Priority controls when this restriction runs alongside other shipping rules. Higher numbers run later, and a later rule can remove a choice that an earlier rule kept. Change the priority only when you need a different order, then check the resulting choices in a representative test cart.', 'guide' => 'https://booster.io/docs/woocommerce-shipping-methods-by-products/#booster-v10-s16-shipping_by_products-priority', 'native_by_edition' => array( 'free' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_by_products&active_tab=shipping_by_condition_advanced_options_tab' ), 'reason' => 'Native source surface present' ), 'plus' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_by_products&active_tab=shipping_by_condition_advanced_options_tab' ), 'reason' => 'Native source surface present' ), 'elite' => array( 'applicable' => true, 'urls' => array( 'admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=shipping_by_products&active_tab=shipping_by_condition_advanced_options_tab' ), 'reason' => 'Native source surface present' ) ) ),
