  foreach ( $keys as $key ) { foreach ( array( '', 'option_', 'pre_option_', 'default_option_' ) as $prefix ) { if ( has_filter( $prefix . $key ) ) { return $none; } } }
  if ( has_filter( 'pre_option' ) ) { return $none; }
  $rows = $wpdb->get_results( $wpdb->prepare( "SELECT option_name,option_value FROM {$wpdb->options} WHERE option_name IN (%s,%s,%s)", $keys ), ARRAY_A );
  if ( $wpdb->last_error || ! is_array( $rows ) ) { return $none; } $raw = array(); foreach ( $rows as $row ) { $raw[ $row['option_name'] ] = $row['option_value']; }
  if ( 'yes' !== ( $raw['wcj_shipping_enabled'] ?? 'no' ) ) { return $none; }
  $count = $raw['wcj_shipping_custom_shipping_total_number'] ?? '1';
  if ( ! is_string( $count ) || ! preg_match( '/^[1-9][0-9]{0,2}$/D', $count ) ) { return $none; }
  return array( 'zone' => $zone && 'yes' === ( $raw['wcj_shipping_custom_shipping_w_zones_enabled'] ?? 'no' ), 'legacy' => $legacy ? (int) $count : 0 );
 }
 /** Resolve source-qualified native registrations, never construct extensions or use a dormant mirror. */
 private static function custom_routes( $group ) {
  global $wpdb; $links = array(); $registration = self::custom_registration();
  if ( $registration['zone'] ) {
   $rows = $wpdb->get_results( "SELECT instance_id,zone_id FROM {$wpdb->prefix}woocommerce_shipping_zone_methods WHERE method_id='booster_custom_shipping_w_zones' ORDER BY instance_id LIMIT 1000", ARRAY_A );
   if ( ! $wpdb->last_error && is_array( $rows ) ) { foreach ( $rows as $row ) { if ( preg_match( '/^[1-9][0-9]*$/D', $row['instance_id'] ) ) { $links[] = self::link( admin_url( 'admin.php?page=wc-settings&tab=shipping&instance_id=' . $row['instance_id'] ), 'Custom zone instance #' . $row['instance_id'] . ' (zone ' . $row['zone_id'] . ')' ); } } }
  }
  if ( 'custom-formula' !== $group ) {
   for ( $n = 1; $n <= $registration['legacy']; $n++ ) { $id = 'booster_custom_shipping_' . $n; $links[] = self::link( admin_url( 'admin.php?page=wc-settings&tab=shipping&section=' . $id ), 'Legacy shipping method ' . $id ); }
  }
  return $links ? implode( ' | ', $links ) : 'No eligible configured editor was resolved. ' . self::link( admin_url( wcj_admin_tab_url() . '&wcj-cat=shipping_and_orders&section=shipping&active_tab=custom_shipping_custom_shipping_tab' ), 'Custom method registration' ) . ' No instance or legacy method was created.';
 }
 private static function routes( $g ) {
  $edition = WCJ_Shipping_Description_Job::edition(); $binding = $g['native_by_edition'][ $edition ];
  if ( ! $binding['applicable'] ) { return 'No native control for this group exists in this edition. Existing edition rights are unchanged.'; }
  if ( in_array( $g['group'], array( 'custom-tables', 'custom-formula', 'custom-eligibility', 'custom-rate' ), true ) ) { return self::custom_routes( $g['group'] ); }
  $links = array(); foreach ( $binding['urls'] as $url ) { $links[] = self::link( admin_url( $url ), 'Full settings: ' . $g['label'] ); }
  return implode( ' | ', $links );
 }
 public static function render( $module = '', $selected = array() ) {
  $groups = array_filter( self::groups(), static function ( $g ) use ( $module, $selected ) { return ( ! $module || $module === $g['module'] ) && ( ! $selected || in_array( $g['group'], $selected, true ) ) && self::allowed( $g['module'] ); } );
  if ( ! $groups ) { return; }
  echo '<details class="wcj-shipping-groups"><summary>Shipping: full settings and group help</summary><p>Native edition and role rights remain. Editors and help open in a new tab. After a native change, deliberately discard and load current values in the description task. One rule passing is not proof that a rate is offered.</p><ul>';
  foreach ( $groups as $g ) {
   echo '<li data-shipping-group="' . esc_attr( $g['group'] ) . '"><h4>' . esc_html( $g['label'] ) . '</h4><p>' . esc_html( $g['consequence'] ) . '</p><p>' . esc_html( 'Module: ' . ( wcj_is_module_enabled( $g['module'] ) ? 'on. Other activation and eligibility conditions still apply.' : 'off. Retained settings are not activated by these links.' ) ) . '</p><p>' . self::routes( $g ) . ' | ' . self::link( $g['guide'], 'Help: ' . $g['label'] ) . '</p></li>';
  }
  echo '</ul></details>';
 }
 public static function entry() { if ( current_user_can( 'manage_woocommerce' ) ) { echo '<p><a href="' . esc_url( admin_url( 'admin.php?page=wcj-shipping-delivery-tasks' ) ) . '">Shipping and delivery choices</a></p>'; } }
 public static function register() { if ( current_user_can( 'manage_woocommerce' ) ) { add_submenu_page( 'woocommerce', 'Shipping and delivery choices', 'Shipping choices', 'manage_woocommerce', 'wcj-shipping-delivery-tasks', array( __CLASS__, 'hub' ) ); } }
 public static function hub() {
  if ( ! current_user_can( 'manage_woocommerce' ) ) { wp_die( 'Ask an administrator for access.', '', array( 'response' => 403 ) ); }
  echo '<div class="wrap"><h1>Shipping and delivery choices</h1><p>Choose the outcome. Nothing here creates, enables, prices or quotes a shipping rate merely by opening it.</p><nav aria-label="Shipping purposes"><a href="#shipping-rates">Which rates shoppers see</a> | <a href="#shipping-create">Create a rate</a> | <a href="#shipping-present">How shipping is presented</a> | <a href="#shipping-message">Free-shipping message</a> | <a href="#shipping-why">Why a rate appears</a></nav>';
  $purposes = array( 'rates' => array( 'Which rates shoppers see', array( 'shipping_options', 'shipping_by_order_amount', 'shipping_by_order_qty', 'shipping_by_cities', 'shipping_by_products', 'shipping_by_time', 'shipping_by_user_role' ) ), 'create' => array( 'Create a rate', array( 'shipping' ) ), 'present' => array( 'How shipping is presented', array( 'shipping_description', 'shipping_icons', 'shipping_calculator', 'shipping_time' ) ), 'message' => array( 'Free-shipping message', array( 'left_to_free_shipping' ) ) );
  foreach ( $purposes as $id => $purpose ) {
   echo '<section id="shipping-' . esc_attr( $id ) . '"><h2>' . esc_html( $purpose[0] ) . '</h2>';
   if ( 'rates' === $id && self::allowed( 'shipping_options' ) ) { echo '<p>' . self::link( admin_url( 'admin.php?page=wcj-shipping-hide-job' ), 'Existing hide-other-rates task' ) . '</p>'; }
   if ( 'present' === $id ) { echo '<p>Descriptions/icons are presentation. Calculator address fields can affect quote inputs; delivery time is an estimate, not a guarantee.</p>'; if ( self::allowed( 'shipping_description' ) ) { echo '<p>' . self::link( WCJ_Shipping_Description_Job::url(), 'Edit a shipping description' ) . '</p>'; } }
   if ( 'message' === $id ) { echo '<p>Messages and progress do not create a free shipping rate. The separate Elite discount changes money.</p>'; }
   foreach ( $purpose[1] as $module ) { self::render( $module ); } echo '</section>';
  }
  echo '<section id="shipping-why"><h2>Why a rate appears</h2><p>Use read-only explanations to check what happened for your current cart and customer account. Keep those observations separate from examples based on facts you supply or facts the tool cannot confirm. A supplied example is not a live carrier quote or a prediction of the final shipping choices.</p>';
  if ( class_exists( 'WCJ_Rule_Explanations_Admin' ) ) { echo self::link( admin_url( 'admin.php?page=wcj-rule-explanations' ), 'Existing Rule explanations' ); }
  echo '</section></div>';
 }
 public static function woo_help() {
  global $wpdb; if ( ! self::allowed( 'shipping' ) ) { return; } $registration = self::custom_registration();
  $instance = isset( $_GET['instance_id'] ) && is_string( $_GET['instance_id'] ) ? wp_unslash( $_GET['instance_id'] ) : '';
  $section = isset( $_GET['section'] ) && is_string( $_GET['section'] ) ? wp_unslash( $_GET['section'] ) : '';
  if ( $registration['zone'] && preg_match( '/^[1-9][0-9]*$/D', $instance ) && 'booster_custom_shipping_w_zones' === $wpdb->get_var( $wpdb->prepare( "SELECT method_id FROM {$wpdb->prefix}woocommerce_shipping_zone_methods WHERE instance_id=%d", $instance ) ) ) { self::render( 'shipping', array( 'custom-rate', 'custom-tables', 'custom-formula', 'custom-eligibility' ) ); }
  elseif ( preg_match( '/^booster_custom_shipping_([1-9][0-9]*)$/D', $section, $m ) && (int) $m[1] <= $registration['legacy'] ) { self::render( 'shipping', array( 'custom-rate', 'custom-tables', 'custom-eligibility' ) ); }
 }
 public static function widget_help( $widget ) { if ( is_object( $widget ) && 'wcj_widget_left_to_free_shipping' === ( $widget->id_base ?? '' ) ) { self::render( 'left_to_free_shipping', array( 'free-cart' ) ); } }
}
