add_action( 'woocommerce_settings_shipping', array( 'WCJ_Shipping_Delivery_Groups', 'woo_help' ), 5 );
add_action( 'in_widget_form', array( 'WCJ_Shipping_Delivery_Groups', 'widget_help' ), 20 );
